  const mut = st.running ? st.mode === 1 : (st.done === 1);
  // switch: on for normal, slides to off for the mutant
  const offv = st.running ? (mut ? smooth(T.SW[0], T.SW[1], u) : 0) : (st.done === 1 ? 1 : 0);
  move(knob, [0, (C.KNOB_OFF - C.KNOB_ON) * offv, 0]); glow(knobS, 1 - offv);
  // trolley position
  let x;
  if (fin) x = ST[2];
  else if (u < 0) x = ST[0];
  else if (u < T.M1[0]) x = ST[0];
  else if (u < T.M1[1]) x = lerp(ST[0], ST[1], smooth(T.M1[0], T.M1[1], u));
