  move(car, [x - ST[0] + shake, 0, 0]);
  // forms: A -> B at the precursor pad (early markers, still round) -> C (neuron, late markers) only with MASH1
  const b = fin ? 1 : u < 0 ? 0 : smooth(T.B[0], T.B[1], u);
  const c = mut ? 0 : (fin ? 1 : u < 0 ? 0 : smooth(T.C[0], T.C[1], u));
  show(fA, 1 - b); show(fB, b * (1 - c)); show(fC, c);
