  const u = st.u, stage = !st.running ? (st.done === null ? "stem cell" : mut ? "stuck as precursor" : "neuron") : u < T.B[1] ? "stem cell" : u < T.C[0] + 0.6 || mut ? "precursor" : "neuron";
